select

from cght.t_contract
where open_status = true

    and id like concat('%', #{id}, '%')


    and title like concat('%', #{title}, '%')


    and sign_person like concat('%', #{sign_person}, '%')


    and sign_type = #{sign_type}


    and supplier like concat('%', #{supplier}, '%')


    AND date_sign >= #{queryBegin}


    AND date_sign <= #{queryEnd}


    AND date_rk >= #{rkBegin}


    AND date_rk <= #{rkEnd}


    and finish_step = #{finish_step}


    and has_rk = #{has_rk}


order by id asc

