update cght.t_contract
title = #{c.title}, amount = #{c.amount}, date_sign = #{c.date_sign}, sign_person = #{c.sign_person}, sign_type = #{c.sign_type}, supplier = #{c.supplier}, pay_type = #{c.pay_type}, paycycle_dh = #{c.paycycle_dh}, paycycle_zb = #{c.paycycle_zb}, rate_yfk = #{c.rate_yfk}, rate_dhk = #{c.rate_dhk}, rate_zbj = #{c.rate_zbj}, date_yfk = #{c.date_yfk}, date_dhk = #{c.date_dhk}, date_zbj = #{c.date_zbj}, date_rk = #{c.date_rk}, bz = #{c.bz}, settle_amount = #{c.settle_amount}, hq = #{c.hq}, date_htyj = #{c.date_htyj}, date_fpyj = #{c.date_fpyj}, date_actual_dh = #{c.date_actual_dh}, date_ruzlyj = #{c.date_ruzlyj}, finish_step = #{c.finish_step}, has_rk = #{c.has_rk}
where id = #{c.id}
